<?php
require_once __DIR__.'/config/app.php';require_once __DIR__.'/config/koneksi.php';require_login();$pageTitle='Jurnal Kegiatan';$role=current_user()['role'];$sid=(int)(current_user()['siswa_id']??0);$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='delete'){if($role==='admin')$pdo->prepare("DELETE FROM jurnal WHERE id=?")->execute([$id]);else $pdo->prepare("DELETE FROM jurnal WHERE id=? AND siswa_id=?")->execute([$id,$sid]);flash('success','Jurnal dihapus.');redirect('jurnal.php');}
 $student=$role==='admin'?(int)($_POST['siswa_id']??0):$sid;$date=$_POST['tanggal']??'';$activity=trim($_POST['kegiatan']??'');$result=trim($_POST['hasil']??'');$obstacle=trim($_POST['kendala']??'');
 if(!$student||!$date||$activity==='')$errors[]='Siswa, tanggal, dan kegiatan wajib diisi.';
 if(!$errors){if($a==='create')$q=$pdo->prepare("INSERT INTO jurnal(siswa_id,tanggal,kegiatan,hasil,kendala) VALUES(?,?,?,?,?)");else $q=$pdo->prepare("UPDATE jurnal SET siswa_id=?,tanggal=?,kegiatan=?,hasil=?,kendala=? WHERE id=?".($role==='siswa'?" AND siswa_id=?":""));$vals=[$student,$date,$activity,$result,$obstacle];if($a==='create')$q->execute($vals);else{$vals[]=$id;if($role==='siswa')$vals[]=$sid;$q->execute($vals);}flash('success','Jurnal berhasil disimpan.');redirect('jurnal.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM jurnal WHERE id=?".($role==='siswa'?" AND siswa_id=?":""));$role==='siswa'?$q->execute([(int)$_GET['edit'],$sid]):$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$students=$pdo->query("SELECT id,nama FROM siswa ORDER BY nama")->fetchAll();$search=trim($_GET['q']??'');$sql="SELECT j.*,s.nama FROM jurnal j JOIN siswa s ON s.id=j.siswa_id WHERE (s.nama LIKE ? OR j.kegiatan LIKE ?)";$params=["%$search%","%$search%"];if($role==='siswa'){$sql.=" AND j.siswa_id=?";$params[]=$sid;}$sql.=" ORDER BY j.tanggal DESC,j.id DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();include __DIR__.'/partials/header.php';?>
<div class="page-head"><div><h1>Jurnal Kegiatan</h1><div class="muted">Catat aktivitas harian selama PKL.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?>
<div class="card"><h3><?=$edit?'Edit Jurnal':'Input Jurnal'?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><?php if($role==='admin'):?><div class="field"><label>Siswa *</label><select name="siswa_id" required><option value="">Pilih siswa</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=($edit['siswa_id']??'')==$s['id']?'selected':''?>><?=e($s['nama'])?></option><?php endforeach;?></select></div><?php endif;?><div class="field"><label>Tanggal *</label><input type="date" name="tanggal" required value="<?=e($edit['tanggal']??date('Y-m-d'))?>"></div><div class="field full"><label>Kegiatan *</label><textarea name="kegiatan" required placeholder="Jelaskan kegiatan hari ini"><?=e($edit['kegiatan']??'')?></textarea></div><div class="field"><label>Hasil</label><textarea name="hasil"><?=e($edit['hasil']??'')?></textarea></div><div class="field"><label>Kendala</label><textarea name="kendala"><?=e($edit['kendala']??'')?></textarea></div></div><div class="form-actions"><button class="btn">Simpan Jurnal</button><?php if($edit):?><a class="btn secondary" href="jurnal.php">Batal</a><?php endif;?></div></form></div>
<div class="card"><form class="filters"><input name="q" value="<?=e($search)?>" placeholder="Cari nama siswa/kegiatan"><button class="btn">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Tanggal</th><?php if($role==='admin'):?><th>Siswa</th><?php endif;?><th>Kegiatan</th><th>Hasil</th><th>Kendala</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><?php if($role==='admin'):?><td><?=e($r['nama'])?></td><?php endif;?><td><?=e($r['kegiatan'])?></td><td><?=e($r['hasil'])?></td><td><?=e($r['kendala'])?></td><td><div class="actions"><a class="btn secondary small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" data-confirm="Hapus jurnal ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Belum ada jurnal.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/partials/footer.php';?>
